            background-color: var(--primary-color);
            color: white;
            padding: 15px 40px;
            text-decoration: none;
            font-size: 18px;
            border-radius: 2px;
            transition: opacity 0.3s;
            display: inline-block;
        }
        .btn:hover {
            opacity: 0.9;
        }
        .section-title {
            text-align: center;
            margin-bottom: 40px;
            font-size: 32px;
            font-weight: 300;
        }
        .categories {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 30px;
            margin-bottom: 80px;
        }
        .category-card {
            height: 400px;
            background-color: #ddd;
            position: relative;
            display: flex;
            align-items: flex-end;
            padding: 30px;
            text-decoration: none;
            color: var(--white);
            transition: transform 0.3s;
            overflow: hidden;
            border-radius: 4px;
        }
        .category-card:hover {
            transform: translateY(-10px);
        }
        .category-card span {
            font-size: 24px;
            font-weight: 500;
            background: rgba(0,0,0,0.3);
            padding: 5px 15px;
            border-radius: 2px;
        }
        .cat-1 { background-color: #d4cdc3; }
        .cat-2 { background-color: #c8d1c8; }
        .cat-3 { background-color: #ddd5d0; }

