            background-color: #f0efed;
            padding: 60px 0;
            border-top: 1px solid var(--border-color);
            text-align: center;
            color: var(--light-text);
        }
        .footer-links {
            margin-bottom: 20px;
            display: flex;
            justify-content: center;
            gap: 20px;
        }
        .footer-links a {
            color: var(--light-text);
            text-decoration: none;
            font-size: 14px;
        }
    </style>
</head>
